        row.append(1 if grid[r][c] == 9 else 0)
    binary_pattern.append(row)

# Find active bounding box
active_rows = set(r for r in range(31) if any(binary_pattern[r][c] for c in range(27)))
active_cols = set(c for c in range(27) if any(binary_pattern[r][c] for r in range(31)))

start_row, end_row = min(active_rows), max(active_rows)
start_col, end_col = min(active_cols), max(active_cols)

active_height = end_row - start_row + 1
active_width = end_col - start_col + 1

print(f"Active region: rows {start_row}-{end_row}, cols {start_col}-{end_col}")
print(f"Active region size: {active_height}x{active_width}")

# Extract active region
active_region = []
for r in range(start_row, end_row + 1):
    active_region.append(binary_pattern[r][start_col:end_col + 1])

# Check for horizontal and vertical symmetry
def is_horizontal_symmetry(pattern):
    for row in pattern:
        for i in range(len(row) // 2):
            if row[i] != row[len(row) - 1 - i]:
                return False
    return True

def is_vertical_symmetry(pattern):
    for i in range(len(pattern) // 2):
        for j in range(len(pattern[0])):
            if pattern[i][j] != pattern[len(pattern) - 1 - i][j]:
                return False
    return True

print(f"\nHorizontal symmetry: {is_horizontal_symmetry(active_region)}")
print(f"Vertical symmetry: {is_vertical_symmetry(active_region)}")

# Try 90/180/270 rotation
import copy
def rotate_90(pattern):
    return [list(x)[::-1] for x in zip(*pattern)]

def rotate_180(pattern):
    return rotate_90(rotate_90(pattern))

def rotate_270(pattern):
    return rotate_90(rotate_270(pattern))

# Check if any rotation is symmetric
print("\nChecking for symmetries...")
for name, func in [("180", rotate_180), ("90+90", rotate_180)]:
    rotated = func(active_region)
    if rotated == active_region:
        print(f"It is {name}-point symmetric!")

